SELECT customer_id
FROM sales_orders
WHERE customer_id >= 4;

SELECT customer_id, COUNT(*) AS order_count
FROM sales_orders
GROUP BY customer_id;

-- Mapping from orders to sales_orders based on evidence 7a8c9379083f2c2b718b841aebba0400f87a25344cb06d74fbeb411d2b3e8aad
WITH recent_orders AS (
    SELECT customer_id FROM sales_orders WHERE id >= 104
)
SELECT customer_id FROM recent_orders;

SELECT customers.id AS customer_id,
       customers.display_name AS full_name
FROM customers;

SELECT id AS customer_id, display_name AS full_name
FROM customers
WHERE display_name LIKE 'A%';

SELECT c.id AS customer_id, c.display_name AS full_name
FROM customers AS c
JOIN sales_orders AS o ON o.customer_id = c.id;

SELECT display_name AS full_name, COUNT(*) AS customer_count
FROM customers
GROUP BY display_name;

SELECT c.id AS customer_id, CAST(s.total_amount * 100 AS BIGINT) AS total_cents
FROM customers c
JOIN sales_orders s ON s.customer_id = c.id;

SELECT c.id AS customer_id, strftime('%Y-%m-%d', c.signup_ts) AS signup_date
FROM main.customers c
WHERE c.signup_ts >= '2024-01-01';

WITH signup_days AS (
    SELECT id AS customer_id, signup_ts FROM customers
)
SELECT strftime('%Y-%m-%d', signup_ts) AS signup_date
FROM signup_days
WHERE signup_ts BETWEEN '2024-01-01' AND '2024-12-31';

SELECT c.id AS customer_id, cs.status_description AS customer_status
FROM main.customers c
LEFT JOIN main.customer_status cs ON c.status_code = cs.status_code;

SELECT customers.id AS customer_id
FROM customers
WHERE customers.account_state = 'OPEN';

SELECT o.id AS order_id, (c.account_state = 'OPEN') AS customer_active
FROM sales_orders AS o
JOIN customers AS c ON c.id = o.customer_id;

SELECT id AS customer_id
FROM customers
WHERE account_state <> 'OPEN';

SELECT id AS customer_id
FROM customers
WHERE account_state <> 'OPEN';

SELECT c.id AS customer_id, cs.status_description AS customer_status
FROM customers c
LEFT JOIN customer_status cs ON c.status_code = cs.status_code;
